SELECT analytics_budget_facts.cost_center, AVG(analytics_budget_facts.budget_variance_pct) AS budget_variance_pct FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2024 AND analytics_budget_facts.month = 5 AND analytics_budget_facts.department = 'department_08' AND analytics_budget_facts.expense_category = 'expense_03' GROUP BY analytics_budget_facts.cost_center ORDER BY budget_variance_pct DESC, analytics_budget_facts.cost_center ASC LIMIT 15
